  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_1,v_c_ben,1,'character','Der nächste Zug fährt über Köln nach Berlin.','قطار بعدی از مسیر کلن به برلین می‌رود.',52,NULL,NULL,NULL,NULL,'[{"surface":"Der","lemma":"der","translation":"حرف تعریف","partOfSpeech":"article"},{"surface":"nächste","lemma":"nächst","translation":"بعدی","partOfSpeech":"adjective"},{"surface":"Zug","lemma":"Zug","translation":"قطار","partOfSpeech":"noun"},{"surface":"fährt","lemma":"fahren","translation":"رفتن با وسیله / راندن","partOfSpeech":"verb"},{"surface":"über","lemma":"über","translation":"بالای / درباره","partOfSpeech":"preposition"},{"surface":"Köln","lemma":"Köln","translation":"کلن","partOfSpeech":"noun"},{"surface":"nach","lemma":"nach","translation":"پس از / به","partOfSpeech":"preposition"},{"surface":"Berlin","lemma":"Berlin","translation":"برلین","partOfSpeech":"noun","suffix":"."}]','Vorlieben mit hätte lieber','با hätte lieber ترجیح مؤدبانه بیان می‌شود؛ مصدر یا متمم جمله انتخاب موردنظر را روشن می‌کند.','{"focus":"preference_konjunktiv_ii","structures":["hätte lieber","würde lieber","travel comparison"]}','{"cefr":"B1","course":"de-fa","series":99}');
  SET v_t_1=LAST_INSERT_ID();
