  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_ben,v_c_lena,'Die Entscheidung steht fest','تصمیم قطعی','Die Buchung gelingt, und Lena und Ben gehen gemeinsam zum richtigen Bahnsteig.','رزرو انجام می‌شود و لنا و بن با هم به سکوی درست می‌روند.','story','lena-ben-b1-travel-problems',16,52,180,4,'validated','{"relationship":"friends","context":"travel-connection","cefr":"B1","storyArc":"choose-direct-connection"}');
