  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_ben,1,'character','Die Buchung ist bestätigt, und die Plätze sind reserviert.','رزرو تأیید شده و صندلی‌ها رزرو شده‌اند.',52,NULL,NULL,NULL,NULL,'[{"surface":"Die","lemma":"der","translation":"حرف تعریف","partOfSpeech":"article"},{"surface":"Buchung","lemma":"Buchung","translation":"رزرو","partOfSpeech":"noun"},{"surface":"ist","lemma":"sein","translation":"بودن","partOfSpeech":"verb"},{"surface":"bestätigt","lemma":"bestätigen","translation":"تأیید کردن","partOfSpeech":"verb","suffix":","},{"surface":"und","lemma":"und","translation":"و","partOfSpeech":"conjunction"},{"surface":"die","lemma":"der","translation":"حرف تعریف","partOfSpeech":"article"},{"surface":"Plätze","lemma":"Platz","translation":"جا / فضا","partOfSpeech":"noun"},{"surface":"sind","lemma":"sein","translation":"بودن","partOfSpeech":"verb"},{"surface":"reserviert","lemma":"reservieren","translation":"undefined","partOfSpeech":"verb","suffix":"."}]','Vorlieben mit hätte lieber','با hätte lieber ترجیح مؤدبانه بیان می‌شود؛ مصدر یا متمم جمله انتخاب موردنظر را روشن می‌کند.','{"focus":"preference_konjunktiv_ii","structures":["hätte lieber","würde lieber","travel comparison"]}','{"cefr":"B1","course":"de-fa","series":99}');
  SET v_t_19=LAST_INSERT_ID();
